import { GoogleGenAI, Type } from "@google/genai";

// ==========================================
// AGENT CONFIGURATIONS
// ==========================================

// Agent 1: The Visual Scanner (Objective, Low Temp)
// Goal: Extract facts and find the "Boke" (Blur/Incongruity) point.
const AGENT_A_PROMPT = `
# ROLE
You are **Agent A (The Scanner)**, a forensic visual analyst.
Your job is to deconstruct the image into objective data points. DO NOT be funny. Be cold and precise.

# TASK
Analyze the image and output a JSON object with:
1. "subject": Main character/object.
2. "action": What is happening.
3. "atmosphere": The mood (e.g., awkward, chaotic, sad).
4. "visual_anomaly": The specific detail that makes the image strange, funny, or contradictory (The "Incongruity").
`;

// Agent 2: The Creative Writer (Divergent, High Temp)
// Goal: Generate wild, varied candidates based on the analysis.
const AGENT_B_PROMPT = `
# ROLE
You are **Agent B (The Creative)**, a top-tier comedy writer for variety shows.
You receive a forensic analysis of an image. Your job is to generate 8 distinct "Oogiri" (Image Caption) candidates.

# RULES
1. **Language**: Chinese (Simplified).
2. **Style**: Use Internet slang, cynicism, surrealism, and wordplay.
3. **Diversity**:
   - 2x Narrative (telling a fake story)
   - 2x Monologue (inner voice of the subject)
   - 2x Object Personification (if the subject is an object)
   - 2x "God-level Roast" (breaking the fourth wall)
4. **Input**: You will receive a JSON analysis. Use the "visual_anomaly" as the core of your jokes.
`;

// Agent 3: The Chief Editor (Convergent, Low Temp)
// Goal: Pick the best one and format it perfectly.
const AGENT_C_PROMPT = `
# ROLE
You are **Agent C (The Chief Editor)**. You have zero tolerance for bad comedy.

# TASK
1. Review the candidate list provided by Agent B.
2. Select the **single absolute best** caption.
3. **Refine it**:
   - Make it punchier (remove unnecessary particles).
   - **CRITICAL**: REMOVE ANY TRAILING PUNCTUATION (Periods, Exclamation marks).
   - Ensure it is in Simplified Chinese.

# CRITERIA
- Reject "Dad jokes".
- Reject AI-sounding explanations.
- The winner must be short, shocking, and instantly funny.

# OUTPUT
Output ONLY the final text string. No JSON, no explanations.
`;

// ==========================================
// SERVICE IMPLEMENTATION
// ==========================================

export type ProgressCallback = (stage: string) => void;

export const generateBokeCaption = async (
  base64Image: string, 
  mimeType: string, 
  modelName: string,
  onProgress: ProgressCallback
): Promise<string> => {
  if (!process.env.API_KEY) {
    throw new Error("API Key is missing. Please set process.env.API_KEY.");
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Clean base64 string
  const cleanBase64 = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");
  const imagePart = { inlineData: { mimeType, data: cleanBase64 } };

  try {
    // ---------------------------------------------------------
    // STEP 1: VISUAL ANALYSIS (Agent A)
    // ---------------------------------------------------------
    onProgress("Agent A (Scanner): Extracting visual anomalies...");

    const analysisResponse = await ai.models.generateContent({
      model: modelName,
      contents: {
        parts: [
            imagePart,
            { text: "Analyze this image for Oogiri potential." }
        ]
      },
      config: {
        systemInstruction: AGENT_A_PROMPT,
        temperature: 0.2, // Cold for precision
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            subject: { type: Type.STRING },
            action: { type: Type.STRING },
            atmosphere: { type: Type.STRING },
            visual_anomaly: { type: Type.STRING, description: "The specific contradiction or funny point" }
          },
          required: ["subject", "action", "visual_anomaly"]
        }
      }
    });

    const analysisData = analysisResponse.text;
    console.log("Agent A Output:", analysisData);

    // ---------------------------------------------------------
    // STEP 2: CREATIVE DIVERGENCE (Agent B)
    // ---------------------------------------------------------
    onProgress("Agent B (Writer): Brainstorming 8 comic angles...");

    const creativeResponse = await ai.models.generateContent({
      model: modelName,
      contents: {
        parts: [
            imagePart, // Keep image in context for reference
            { text: `Here is the analysis: ${analysisData}. Generate 8 funny captions now.` }
        ]
      },
      config: {
        systemInstruction: AGENT_B_PROMPT,
        temperature: 1.1, // High for creativity
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            candidates: {
              type: Type.ARRAY,
              items: { type: Type.STRING }
            }
          }
        }
      }
    });

    const candidatesJson = creativeResponse.text;
    console.log("Agent B Output:", candidatesJson);

    // ---------------------------------------------------------
    // STEP 3: SELECTION & POLISH (Agent C)
    // ---------------------------------------------------------
    onProgress("Agent C (Editor): Final polish (Removing punctuation)...");

    const selectionResponse = await ai.models.generateContent({
      model: modelName, // Can use a cheaper model here if optimized, but sticking to selection
      contents: {
        parts: [
            { text: `Here are the candidates: ${candidatesJson}. Pick the best one, polish it, and output raw text.` }
        ]
      },
      config: {
        systemInstruction: AGENT_C_PROMPT,
        temperature: 0.1, // Low for strict formatting
      }
    });

    const finalText = selectionResponse.text?.trim();

    if (!finalText) {
        throw new Error("Agent C failed to return a caption.");
    }

    // Final safety regex to ensure compliance with "No periods" rule
    return finalText.replace(/[。\.！!？\?]+$/, "");

  } catch (error) {
